func columnViewSetDatasetSafe(ds *MemoryDataset){defer appRecover("columnViewSetDatasetSafe");if ds==nil{return};columnViewDestroyFilters();viewDataset=ds;columnViewBuildFilters();columnViewRefreshSafe();appApplyVisualPolish(appHwnd)}
func columnViewRefreshSafe(){defer appRecover("columnViewRefreshSafe");if viewList==0{return};columnViewDeleteColumns();user32.NewProc("SendMessageW").Call(viewList,lvmDeleteAll,0,0);if viewDataset==nil{return};visible:=columnViewVisibleColumns();for i,c:=range visible{p:=appU16(datasetColumnDisplayTitle(c));fmtCol:=lvcfmtLeft;if c.Type==ValueNumber{fmtCol=lvcfmtRight};width:=c.Width;if width<120{width=120};if width>420{width=420};lc:=lvColumn{Mask:lvcfText,Fmt:int32(fmtCol),Cx:int32(width),Text:p,SubItem:int32(i)};user32.NewProc("SendMessageW").Call(viewList,lvmInsertColumnW,uintptr(i),uintptr(unsafe.Pointer(&lc)))};records:=safeFilterRecords(viewDataset,safeSnapshotFilters());for ri,r:=range records{for ci,c:=range visible{txt:=datasetCellText(r,c);p:=appU16(txt);it:=lvItem{Mask:lvifText,Item:int32(ri),SubItem:int32(ci),Text:p,TextMax:int32(len([]rune(txt))+1)};if ci==0{user32.NewProc("SendMessageW").Call(viewList,lvmInsertItemW,0,uintptr(unsafe.Pointer(&it)))}else{user32.NewProc("SendMessageW").Call(viewList,lvmSetItemTextW,uintptr(ri),uintptr(unsafe.Pointer(&it)))}}};send:=user32.NewProc("SendMessageW");count,_,_:=send.Call(viewList,lvmGetItemCount,0,0);appLog("DIAGNOSTICO: item count en listview=%d",int(count));if appSettings.SubtotalEnabled&&appSettings.SubtotalColumn!=""{columnViewAddSubtotal(visible,records)};columnViewAutoFit(visible);columnViewLayoutFilters(currentClientWidth());columnViewApplyFont();var clientRect struct{Left,Top,Right,Bottom int32};user32.NewProc("GetClientRect").Call(viewList,uintptr(unsafe.Pointer(&clientRect)));appLog("DIAGNOSTICO: listview client rect left=%d top=%d right=%d bottom=%d width=%d height=%d",clientRect.Left,clientRect.Top,clientRect.Right,clientRect.Bottom,clientRect.Right-clientRect.Left,clientRect.Bottom-clientRect.Top);if count>0{var itemRect struct{Left,Top,Right,Bottom int32};itemRect.Left=0;ok,_,_:=send.Call(viewList,lvmGetItemRect,0,uintptr(unsafe.Pointer(&itemRect)));appLog("DIAGNOSTICO: item 0 rect ok=%d left=%d top=%d right=%d bottom=%d width=%d height=%d",ok,itemRect.Left,itemRect.Top,itemRect.Right,itemRect.Bottom,itemRect.Right-itemRect.Left,itemRect.Bottom-itemRect.Top);buf:=make([]uint16,256);readItem:=lvItem{Mask:lvifText,Item:0,SubItem:0,Text:&buf[0],TextMax:256};n,_,_:=send.Call(viewList,0x1073,0,uintptr(unsafe.Pointer(&readItem)));text:="";if n>0{text=string(syscall.UTF16ToString(buf))};appLog("DIAGNOSTICO: item 0 readback LVM_GETITEMTEXTW chars=%d text=%q",int(n),text)};var windowRect struct{Left,Top,Right,Bottom int32};getWindowRect:=user32.NewProc("GetWindowRect");mapWindowPoints:=user32.NewProc("MapWindowPoints");if ret,_,_:=getWindowRect.Call(viewList,uintptr(unsafe.Pointer(&windowRect)));ret!=0{mapWindowPoints.Call(0,appHwnd,uintptr(unsafe.Pointer(&windowRect)),2);appLog("DIAGNOSTICO: listview window rect coords padre left=%d top=%d right=%d bottom=%d width=%d height=%d",windowRect.Left,windowRect.Top,windowRect.Right,windowRect.Bottom,windowRect.Right-windowRect.Left,windowRect.Bottom-windowRect.Top)}else{appLog("DIAGNOSTICO: GetWindowRect listview fallo")};header,_,_:=send.Call(viewList,lvmGetHeader,0,0);if header!=0{var headerRect struct{Left,Top,Right,Bottom int32};if ret,_,_:=getWindowRect.Call(header,uintptr(unsafe.Pointer(&headerRect)));ret!=0{appLog("DIAGNOSTICO: header rect screen left=%d top=%d right=%d bottom=%d width=%d height=%d",headerRect.Left,headerRect.Top,headerRect.Right,headerRect.Bottom,headerRect.Right-headerRect.Left,headerRect.Bottom-headerRect.Top)}else{appLog("DIAGNOSTICO: GetWindowRect header fallo")}}else{appLog("DIAGNOSTICO: listview header handle=0")};user32.NewProc("InvalidateRect").Call(viewList,0,1);user32.NewProc("UpdateWindow").Call(viewList);user32.NewProc("InvalidateRect").Call(appHwnd,0,1);flags:=uintptr(0x1|0x4|0x100|0x80);user32.NewProc("RedrawWindow").Call(viewList,0,0,flags);appLog("DIAGNOSTICO: repintado forzado InvalidateRect+UpdateWindow+RedrawWindow; item count en listview=%d",int(count));appLog("DIAGNOSTICO: render síncrono completo; registros=%d",len(records))}
func safeSnapshotFilters()[]safeFilter{if viewDataset==nil{return nil};filters:=make([]safeFilter,0,len(viewFilters));for id,h:=range viewFilters{text:=strings.ToLower(strings.TrimSpace(appGetEdit(h)));if text==""{continue};for _,c:=range viewDataset.Columns{if c.ID==id{filters=append(filters,safeFilter{column:c,text:text});break}}};return filters}
func safeFilterRecords(ds *MemoryDataset,filters []safeFilter)[]DatasetRecord{if ds==nil{return nil};if len(filters)==0{return append([]DatasetRecord(nil),ds.Records...)};out:=make([]DatasetRecord,0,len(ds.Records));for _,r:=range ds.Records{ok:=true;for _,f:=range filters{if !strings.Contains(strings.ToLower(datasetCellText(r,f.column)),f.text){ok=false;break}};if ok{out=append(out,r)}};return out}
func appApplyVisualPolish(parent uintptr){defer appRecover("appApplyVisualPolish");if parent==0{return};theme:=syscall.NewLazyDLL("uxtheme.dll");setTheme:=theme.NewProc("SetWindowTheme");gdi:=syscall.NewLazyDLL("gdi32.dll");createFont:=gdi.NewProc("CreateFontW");face:=appU16("Segoe UI");size:=appSettings.FontSize;if size<8||size>32{size=10};font,_,_:=createFont.Call(uintptr(int32(-size)),0,0,0,600,0,0,0,1,0,0,0,0,uintptr(unsafe.Pointer(face)));explorer:=appU16("Explorer");buttons:=[]struct{id,x,w uintptr}{{appIDOpen,12,125},{appIDColumns,145,105},{appIDConfig,258,135}};for _,b:=range buttons{h:=uintptr(0);switch b.id{case appIDOpen:h=appOpenButton;case appIDColumns:h=appColumnsButton;case appIDConfig:h=appConfigButton};if h==0{h=findChildByID(parent,"BUTTON",b.id)};if h==0{continue};setTheme.Call(h,uintptr(unsafe.Pointer(explorer)),0);if font!=0{user32.NewProc("SendMessageW").Call(h,WM_SETFONT,font,1)};user32.NewProc("MoveWindow").Call(h,b.x,7,b.w,30,1)};status:=appStatus;if status==0{status=findChildByID(parent,"STATIC",appIDStatus)};if status!=0{if font!=0{user32.NewProc("SendMessageW").Call(status,WM_SETFONT,font,1)};user32.NewProc("MoveWindow").Call(status,410,11,uintptr(maxInt(240,currentClientWidth()-430)),22,1)}}